[Better Approach - 1] Using Prefix Sum - O(n) Time and O(n) SpaceThe idea is to precompute the prefix sum array where each element at index i stores the sum of elements from index 0 to i-1. Using this, we can compute the sum of any subarray in constant time O(1) using the difference of two prefix values. This eliminates the need to iterate over each subarray element repeatedly.
            C++

    #include <iostream>
#include <vector>
using namespace std;

int maxSubarraySum(vector<int>& arr, int k) {
    int n = arr.size();
    vector<int> prefix(n + 1, 0);

    // build prefix sum array
    for (int i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + arr[i];
    }

    int maxSum = 0;

    // compute sum of each subarray of size k
    // using prefix array
    for (int i = 0; i <= n - k; i++) {
        int j = i + k - 1;
        int currSum = prefix[j + 1] - prefix[i];

        // update maximum sum
        maxSum = max(maxSum, currSum);
    }

    return maxSum;
}

int main() {
    vector<int> arr = {2, 1, 5, 1, 3, 2};
    int k = 3;
    cout << maxSubarraySum(arr, k) << endl;
    return 0;
}


