[Better Approach - 2] Sliding Window using Queue - O(n) Time and O(k) SpaceThe idea is to use a queue to maintain a window of the last k elements as we iterate through the array. We keep track of the current window sum by adding the new element to the sum and removing the oldest element (from the front of the queue) once the size exceeds k. At each step where the window size is exactly k, we update the maximum sum encountered so far.This ensures that we process each element exactly once and maintain the sliding window efficiently.
            C++

    #include <iostream>
#include <vector>
#include <queue>
using namespace std;

int maxSubarraySum(vector<int>& arr, int k) {
    int n = arr.size();
    queue<int> q;
    int sum = 0, maxSum = 0;

    for (int i = 0; i < n; i++) {
        sum += arr[i];
        q.push(arr[i]);

        // maintain window of size k
        if (q.size() > k) {
            sum -= q.front();
            q.pop();
        }

        // update maximum when window size becomes k
        if (q.size() == k) {
            maxSum = max(maxSum, sum);
        }
    }

    return maxSum;
}

int main() {
    vector<int> arr = {2, 1, 5, 1, 3, 2};
    int k = 3;
    cout << maxSubarraySum(arr, k) << endl;
    return 0;
}


